    "description": "«Не мог не прийти», но «ни один не пришёл». НЕ — отрицание, двойное НЕ — утверждение; НИ — усиление отрицания (ни капли) и повторяющийся союз (ни рыба ни мясо); в придаточных — кто бы ни, что бы ни. Ловушка: в вопросе и восклицании — НЕ.",
