// Site root derived from this script's own URL (js/lessons.js → ../), so media paths work from any page
const SITE_ROOT =
  typeof document !== "undefined" && document.currentScript
    ? new URL("../", document.currentScript.src).href
    : "";

const NO_UI = typeof document !== "undefined" && Boolean(document.currentScript?.hasAttribute("data-no-ui"));

const SUBJECT_LABELS = {
  math: "Математика",
  russian: "Русский язык"
};

// Selection State
const state = {
  subject: null,
  grade: null,
  topic: null,
  searchQuery: "",
  activeFilter: "all" // all | uncompleted | completed | favorites | video
};

// Progress and bookmarks live in cookies (js/store.js), so nothing needs registration
function getProgressSet() {
  return window.IntStore ? window.IntStore.completed() : new Set();
}

function getBookmarksSet() {
  return window.IntStore ? window.IntStore.bookmarks() : new Set();
}

function toggleBookmark(lessonId) {
  return window.IntStore ? window.IntStore.toggleBookmark(lessonId) : false;
}

// Celebration Confetti
function launchConfetti() {
  const container = document.createElement("div");
  container.className = "confetti-container";
  container.setAttribute("aria-hidden", "true");
  document.body.appendChild(container);

  const colors = ["#2563eb", "#10b981", "#f59e0b", "#ec4899", "#8b5cf6", "#06b6d4"];
  for (let i = 0; i < 40; i++) {
    const piece = document.createElement("div");
    piece.className = "confetti-piece";
    piece.style.left = `${Math.random() * 100}%`;
    piece.style.backgroundColor = colors[Math.floor(Math.random() * colors.length)];
    piece.style.animationDelay = `${Math.random() * 0.4}s`;
    piece.style.transform = `scale(${0.5 + Math.random() * 0.8})`;
    container.appendChild(piece);
  }

  setTimeout(() => {
    container.remove();
  }, 2400);
}

// Browser-only UI Initialization (the admin page loads this file with data-no-ui just to read LESSONS)
if (typeof document !== "undefined" && !NO_UI) {
  initLessonsApp();
}

function initLessonsApp() {
  window.IntStore?.setLessons(LESSONS);
  window.updateProfileUI?.();
  const subjectStep = document.getElementById("subjectStep");
const gradeStep = document.getElementById("gradeStep");
const topicStep = document.getElementById("topicStep");
const gradeHint = document.getElementById("gradeHint");
const topicHint = document.getElementById("topicHint");
const topicChoices = document.getElementById("topicChoices");
const resultsPanel = document.getElementById("resultsPanel");
const resultsTitle = document.getElementById("resultsTitle");
const grid = document.getElementById("lessonsGrid");
const empty = document.getElementById("lessonsEmpty");
const resetFlowBtn = document.getElementById("resetFlow");
const flowProgress = document.getElementById("flowProgress");
const lessonSearchInput = document.getElementById("lessonSearch");
const clearSearchBtn = document.getElementById("clearSearch");
const overallProgressBar = document.getElementById("overallProgressBar");
const overallProgressText = document.getElementById("overallProgressText");
const flowBox = document.getElementById("flowBox");

// the furthest step the pupil has reached: 1 subject, 2 grade, 3 video
let maxPane = 1;
// no motion while the page restores a choice from the link
let booting = true;

/**
 * Steps live in one box: a choice swaps in the next step in place instead of scrolling down
 */
function showPane(n) {
  if (!flowBox) return;
  const prev = Number(flowBox.dataset.pane);
  maxPane = Math.max(maxPane, n);
  if (prev !== n) {
    const from = flowBox.offsetHeight;
    flowBox.dataset.pane = String(n);
    if (!booting && motionOn()) {
      const to = flowBox.offsetHeight;
      const ease = "cubic-bezier(0.16, 1, 0.3, 1)";
      flowBox.animate([{ height: `${from}px` }, { height: `${to}px` }], { duration: 340, easing: ease });
      flowBox.querySelector(`[data-pane-id="${n}"]`)?.animate(
        [{ opacity: 0, transform: `translateX(${n > prev ? 28 : -28}px)` }, { opacity: 1, transform: "none" }],
        { duration: 340, easing: ease }
      );
    }
  }
  updateProgressIndicator();
  if (!booting) {
    // keep the box in sight when it was scrolled half away
    const top = flowBox.getBoundingClientRect().top;
    if (top < 0) flowBox.scrollIntoView({ block: "start", behavior: motionOn() ? "smooth" : "auto" });
    flowBox.querySelector(`[data-pane-id="${n}"] .flow-back, [data-pane-id="${n}"] button`)?.focus({ preventScroll: true });
  }
}

/**
 * Update step progress indicator
 */
function updateProgressIndicator() {
  if (!flowProgress) return;
  const pane = Number(flowBox?.dataset.pane || 1);
  flowProgress.querySelectorAll("[data-step-indicator]").forEach((step) => {
    const n = Number(step.dataset.stepIndicator);
    step.classList.toggle("active", n === pane);
    step.classList.toggle("completed", n < pane || (n === 3 && Boolean(state.topic)));
    step.disabled = n > maxPane;
    if (n === pane) step.setAttribute("aria-current", "step");
    else step.removeAttribute("aria-current");
  });
}

/**
 * Update overall course completion summary stats
 */
function updateOverallProgressStats() {
  const completedSet = getProgressSet();
  const total = LESSONS.length;
  const done = completedSet.size;
  const percent = total > 0 ? Math.round((done / total) * 100) : 0;

  if (overallProgressBar) {
    overallProgressBar.style.width = `${percent}%`;
  }
  if (overallProgressText) {
    overallProgressText.textContent = `Пройдено ${done} из ${total} ${plural(total, ["урока", "уроков", "уроков"])} (${percent}%)`;
  }
}

/**
 * URL query string sync (shareable link state)
 */
function updateUrl() {
  const url = new URL(window.location);
  if (state.subject) {
    url.searchParams.set("subject", state.subject);
  } else {
    url.searchParams.delete("subject");
  }
  if (state.grade) {
    url.searchParams.set("grade", state.grade);
  } else {
    url.searchParams.delete("grade");
  }
  if (state.topic) {
    url.searchParams.set("topic", state.topic);
  } else {
    url.searchParams.delete("topic");
  }
  if (state.searchQuery) {
    url.searchParams.set("q", state.searchQuery);
  } else {
    url.searchParams.delete("q");
  }
  window.history.replaceState({}, "", url.toString());
}

/**
 * Indices 0..n-1 in random order (options are shown shuffled so the answer is not always first)
 */
function shuffledIndices(n) {
  const order = Array.from({ length: n }, (_, i) => i);
  for (let i = n - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [order[i], order[j]] = [order[j], order[i]];
  }
  return order;
}

// 1 вопрос, 2 вопроса, 5 вопросов
function plural(n, [one, few, many]) {
  const d = n % 10, h = n % 100;
  if (d === 1 && h !== 11) return one;
  if (d >= 2 && d <= 4 && (h < 12 || h > 14)) return few;
  return many;
}

// A quiz slot is one task or { variants: [task, …] }: every attempt draws one of them
const variantsOf = (q) => (q.variants ? q.variants : [q]);

function quizSummary(lesson) {
  const n = lesson.quiz.length;
  const tasks = lesson.quiz.filter((q) => variantsOf(q)[0].type).length;
  const what = tasks === n ? plural(n, ["задание", "задания", "заданий"]) : plural(n, ["вопрос", "вопроса", "вопросов"]);
  return `Мини-тест: ${n} ${what}${lesson.video || lesson.videoId ? " после видео" : ""}`;
}

/**
 * Build lesson card HTML element
 */
function createCard(lesson) {
  const card = document.createElement("article");
  card.className = "lesson-card";
  card.id = `card-${lesson.id}`;
  if (state.topic === lesson.id) {
    card.classList.add("highlighted");
  }

  const completedSet = getProgressSet();
  const isCompleted = completedSet.has(lesson.id);
  if (isCompleted) {
    card.classList.add("is-completed");
  }

  const bookmarksSet = getBookmarksSet();
  const isBookmarked = bookmarksSet.has(lesson.id);

  const quizData = lesson.quiz || [];
  const hasQuiz = quizData.length > 0;

  const takeawayHtml = lesson.takeaway
    ? `<div class="lesson-takeaway">
        <span class="takeaway-icon">💡</span>
        <div class="takeaway-text"><strong>Главное правило:</strong> ${lesson.takeaway}</div>
      </div>`
    : "";

  const quizHtml = hasQuiz
    ? `
      <div class="quiz-lock-status" id="quiz-status-${lesson.id}">
        <div class="quiz-lock-badge">
          <span class="quiz-lock-icon">${isCompleted ? "✓" : ""}</span>
          <span class="quiz-lock-text">${isCompleted ? "Тест успешно пройден" : quizSummary(lesson)}</span>
        </div>
        <button class="quiz-unlock-btn" type="button" data-unlock="${lesson.id}">
          ${isCompleted ? "Пройти снова →" : "Пройти тест →"}
        </button>
      </div>
    `
    : "";

  let mediaOpen;
  if (lesson.video) {
    mediaOpen = `
    <div class="lesson-media" data-src="${SITE_ROOT}${lesson.video.src}" role="button" tabindex="0" aria-label="Смотреть видео: ${lesson.title}">
      <img src="${SITE_ROOT}${lesson.video.poster}" alt="${lesson.title}" loading="lazy" decoding="async">
      <span class="play-badge" aria-hidden="true"></span>
      ${lesson.video.duration ? `<span class="video-duration">${lesson.video.duration}</span>` : ""}`;
  } else if (lesson.videoId) {
    mediaOpen = `
    <div class="lesson-media" data-video="${lesson.videoId}" role="button" tabindex="0" aria-label="Смотреть видео: ${lesson.title}">
      <img src="https://i.ytimg.com/vi/${lesson.videoId}/hqdefault.jpg" alt="${lesson.title}" loading="lazy">
      <span class="play-badge" aria-hidden="true"></span>`;
  } else {
    mediaOpen = `
    <div class="lesson-media is-pending">
      <div class="pending-media">
        <span class="pending-icon" aria-hidden="true">🎬</span>
        <span class="pending-text">Видео готовится</span>
        <span class="pending-topic">${lesson.topic}</span>
      </div>`;
  }

  card.innerHTML = `
    ${mediaOpen}
      <div class="lesson-card-top-actions">
        <button class="card-icon-action bookmark-action-btn ${isBookmarked ? "active" : ""}" type="button" data-bookmark="${lesson.id}" aria-label="${isBookmarked ? "Удалить из закладок" : "Сохранить в закладки"}" title="${isBookmarked ? "В избранном" : "В закладки"}">
          <span class="bookmark-icon">${isBookmarked ? "★" : "☆"}</span>
        </button>
        <button class="card-icon-action share-action-btn" type="button" data-share="${lesson.id}" aria-label="Поделиться уроком" title="Скопировать ссылку на урок">
          <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M4 12v8a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2v-8"/><polyline points="16 6 12 2 8 6"/><line x1="12" y1="2" x2="12" y2="15"/></svg>
        </button>
      </div>
      ${isCompleted ? `<div class="lesson-completed-ribbon" title="Урок и тест пройдены">✓ Изучено</div>` : ""}
    </div>
    <div class="lesson-body">
      <div class="lesson-badge-wrap">
        <span class="lesson-subject">${SUBJECT_LABELS[lesson.subject] || lesson.subject}</span>
        <span class="lesson-grade-badge">${lesson.grade} класс</span>
        ${lesson.topic ? `<span class="lesson-topic-badge">${lesson.topic}</span>` : ""}
      </div>
      <h3>${lesson.title}</h3>
      <p class="lesson-desc-text">${lesson.description}</p>
      ${takeawayHtml}
      ${quizHtml}
    </div>
  `;

  return card;
}

/**
 * Filter lessons based on state, search query, and filter tab
 */
function getFilteredLessons() {
  const query = state.searchQuery.trim().toLowerCase();
  const completedSet = getProgressSet();
  const bookmarksSet = getBookmarksSet();

  return LESSONS.filter((l) => {
    // 1. Text search filter
    if (query) {
      const matchText =
        l.title.toLowerCase().includes(query) ||
        l.topic.toLowerCase().includes(query) ||
        l.description.toLowerCase().includes(query) ||
        (l.takeaway && l.takeaway.toLowerCase().includes(query)) ||
        (SUBJECT_LABELS[l.subject] && SUBJECT_LABELS[l.subject].toLowerCase().includes(query)) ||
        (l.quiz && l.quiz.some((q) => variantsOf(q).some((v) => v.question.toLowerCase().includes(query))));
      if (!matchText) return false;
    } else {
      // Step-by-step filters if no search query
      if (state.subject && l.subject !== state.subject) return false;
      if (state.grade && l.grade !== state.grade) return false;
      if (state.topic && l.id !== state.topic) return false;
    }

    // 2. Tab filter (All / Uncompleted / Completed / Favorites)
    if (state.activeFilter === "completed" && !completedSet.has(l.id)) return false;
    if (state.activeFilter === "uncompleted" && completedSet.has(l.id)) return false;
    if (state.activeFilter === "favorites" && !bookmarksSet.has(l.id)) return false;
    if (state.activeFilter === "video" && !(l.video || l.videoId)) return false;

    return true;
  });
}

/**
 * Render topic filter chips
 */
function renderTopics() {
  if (!state.subject) {
    topicStep?.classList.add("is-locked");
    if (topicChoices) topicChoices.innerHTML = "";
    return;
  }

  const available = LESSONS.filter((l) => {
    const matchSub = l.subject === state.subject;
    const matchGrade = !state.grade || l.grade === state.grade;
    return matchSub && matchGrade;
  });

  if (available.length === 0) {
    if (topicChoices) {
      topicChoices.innerHTML = `<p class="flow-hint">Для выбранного класса уроки скоро появятся.</p>`;
    }
    return;
  }

  const topicChips = available
    .map((l) => {
      const isSelected = state.topic === l.id;
      const label = state.grade ? l.topic || l.title : `${l.grade} кл · ${l.topic || l.title}`;
      return `<button class="topic-chip ${isSelected ? "selected" : ""}" type="button" data-topic="${l.id}">${label}</button>`;
    })
    .join("");

  if (topicChoices) topicChoices.innerHTML = topicChips;
  topicStep?.classList.remove("is-locked");
  updateProgressIndicator();
}

/**
 * Render filtered lessons without choppy screen tearing
 */
function renderLessons() {
  const hasSearch = Boolean(state.searchQuery.trim());

  // Show results panel if subject selected or search query entered
  if (!state.subject && !hasSearch && state.activeFilter === "all") {
    resultsPanel?.classList.add("is-locked");
    return;
  }

  const filtered = getFilteredLessons();

  let headingText = "";
  if (hasSearch) {
    headingText = `Результаты поиска: «${state.searchQuery}» (${filtered.length})`;
  } else if (state.activeFilter === "favorites") {
    headingText = `Избранные уроки (${filtered.length})`;
  } else if (state.activeFilter === "video") {
    headingText = `Видеоуроки (${filtered.length})`;
  } else if (state.activeFilter === "completed") {
    headingText = `Пройденные уроки (${filtered.length})`;
  } else {
    const subjectTitle = SUBJECT_LABELS[state.subject] || "Все предметы";
    const gradeTitle = state.grade ? ` · ${state.grade} класс` : " · Все классы (5–9)";
    headingText = `${subjectTitle}${gradeTitle} (${filtered.length} ${filtered.length === 1 ? "урок" : "уроков"})`;
  }

  if (resultsTitle) {
    resultsTitle.textContent = headingText;
  }

  if (grid) {
    grid.innerHTML = "";
    filtered.forEach((lesson) => {
      grid.appendChild(createCard(lesson));
    });
  }

  if (empty) {
    empty.hidden = filtered.length > 0;
    if (filtered.length === 0) {
      empty.textContent = hasSearch
        ? `По запросу «${state.searchQuery}» ничего не найдено. Попробуйте другой запрос или сбросьте фильтры.`
        : state.activeFilter === "favorites"
        ? "В закладках пока пусто. Нажмите звёздочку ★ на любом уроке, чтобы сохранить его сюда."
        : "Для выбранной комбинации уроков не найдено.";
    }
  }

  resultsPanel?.classList.remove("is-locked");
  updateProgressIndicator();
  updateOverallProgressStats();
  updateUrl();
}

/**
 * Video player: native <video> for self-hosted lessons, YouTube embed for legacy ids
 */
function playVideo(media) {
  const src = media.dataset.src;
  const videoId = media.dataset.video;
  if (!src && !videoId) return;
  if (media.querySelector("video, iframe")) return;

  const card = media.closest(".lesson-card");
  const statusBox = card?.querySelector(".quiz-lock-status");

  if (src) {
    const poster = media.querySelector("img")?.getAttribute("src") || "";
    media.innerHTML = `<video src="${src}" poster="${poster}" controls autoplay playsinline preload="auto"></video>`;
    const video = media.querySelector("video");
    let counted = false;
    video.addEventListener("play", () => {
      if (!counted) {
        counted = true;
        window.IntStats?.track("video_start", card?.querySelector(".quiz-unlock-btn")?.dataset.unlock);
      }
      // only one lesson plays at a time
      document.querySelectorAll(".lesson-media video").forEach((other) => {
        if (other !== video) other.pause();
      });
    });
    video.addEventListener("ended", () => {
      const lessonId = card?.querySelector(".quiz-unlock-btn")?.dataset.unlock;
      window.IntStats?.track("video_end", lessonId);
      if (lessonId) openQuizAfterVideo(lessonId);
    });
    const lessonId = card?.querySelector(".quiz-unlock-btn")?.dataset.unlock;
    const stop = LESSONS.find((l) => l.id === lessonId)?.video?.pause;
    if (stop) videoStop(media, video, stop);
    video.play()?.catch(() => {});
  } else {
    media.innerHTML = `<iframe src="https://www.youtube-nocookie.com/embed/${videoId}?autoplay=1&enablejsapi=1&rel=0&origin=${encodeURIComponent(location.origin)}" title="Видеоурок YouTube" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture" allowfullscreen></iframe>`;
  }
  media.style.cursor = "default";

  if (statusBox) {
    const textElem = statusBox.querySelector(".quiz-lock-text");
    const iconElem = statusBox.querySelector(".quiz-lock-icon");
    if (textElem) textElem.textContent = "Идёт видеоурок. Тест откроется по завершении";
    if (iconElem) iconElem.textContent = "▶";
  }
}

/**
 * Pause on the puzzle: the video stops once, right after its opening puzzle is asked, and offers three
 * answers to guess from. «Смотреть решение» plays on; seeking past the moment (or pressing play) skips it.
 * lesson.video.pause = { at: seconds, question, options: [...], answer: index }
 */
function videoStop(media, video, stop) {
  let done = false;
  let last = 0;
  let panel = null;
  const close = () => {
    if (!panel) return;
    const p = panel;
    panel = null;
    p.classList.add("is-out");
    setTimeout(() => p.remove(), motionOn() ? 220 : 0);
  };
  video.addEventListener("timeupdate", () => {
    const t = video.currentTime;
    // only when playback runs into the moment, not when the viewer jumps over it
    const crossed = !done && last < stop.at && t >= stop.at && t - last < 1.5;
    last = t;
    if (!crossed) return;
    done = true;
    video.pause();
    if (document.fullscreenElement) document.exitFullscreen?.().catch(() => {});
    if (video.webkitDisplayingFullscreen) video.webkitExitFullscreen?.();
    show();
  });
  video.addEventListener("play", close);

  function show() {
    panel = document.createElement("div");
    panel.className = "vstop";
    panel.setAttribute("role", "group");
    panel.setAttribute("aria-label", "Задачка из видео");
    panel.innerHTML = `
      <p class="vstop-label"><span class="vstop-icon" aria-hidden="true"></span>Пауза — попробуйте ответить сами</p>
      <p class="vstop-q"></p>
      <div class="vstop-opts"></div>
      <p class="vstop-msg" aria-live="polite" hidden></p>
      <button class="btn vstop-go" type="button">Пропустить и смотреть ▶</button>`;
    panel.querySelector(".vstop-q").textContent = stop.question;
    const opts = panel.querySelector(".vstop-opts");
    const msg = panel.querySelector(".vstop-msg");
    const go = panel.querySelector(".vstop-go");
    shuffledIndices(stop.options.length).forEach((i) => {
      const b = document.createElement("button");
      b.type = "button";
      b.className = "vstop-opt";
      b.textContent = stop.options[i];
      b.addEventListener("click", () => {
        const right = i === stop.answer;
        opts.querySelectorAll("button").forEach((x) => { x.disabled = true; });
        b.classList.add(right ? "is-right" : "is-wrong");
        opts.children[[...opts.children].findIndex((x) => x.textContent === stop.options[stop.answer])]?.classList.add("is-right");
        msg.hidden = false;
        msg.className = `vstop-msg ${right ? "is-right" : "is-wrong"}`;
        msg.textContent = right ? "Верно! Теперь посмотрим, как это решить." : `Не совсем: ответ — ${stop.options[stop.answer]}. Сейчас разберёмся почему.`;
        go.textContent = "Смотреть решение ▶";
        go.focus();
      });
      opts.appendChild(b);
    });
    go.addEventListener("click", () => {
      close();
      video.play()?.catch(() => {});
    });
    media.after(panel);
    panel.scrollIntoView({ block: "nearest", behavior: motionOn() ? "smooth" : "auto" });
  }
}

const escapeHtml = (t) => String(t).replace(/[&<>"]/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" }[c]));
// the first sentence of the lesson's rule, as the nudge before a second try
const firstSentence = (t) => (t ? String(t).split(/(?<=[.!?])\s+/)[0] : "");

// the how-to line for task types whose widget has none of its own
const HOW_TO = {
  scales: "Подбирайте x кнопками − и +, пока весы не уравновесятся",
  angle: "Тяните точку на луче или двигайте ползунок",
  numberline: "Нажмите на нужные числа на прямой",
  plane: "Нажмите на нужный узел сетки",
  pick: "Нажмите на нужные части рисунка",
  level: "Подберите значение кнопками − и +",
  "triangle-sum": "Тяните точку, чтобы повернуть угол",
  line: "Подбирайте k и b кнопками − и +",
  strips: "Подбирайте x кнопками − и +",
  rect: "Нажмите на клетку — там будет дальний угол прямоугольника",
  enter: "Введите число или подберите его кнопками − и +",
  roll: "Остановите колесо в нужный момент",
  order: "Нажимайте на карточки по порядку",
  sticks: "Подберите длину кнопками − и +",
  table: "Нажимайте на сетку над каждым x",
  words: "Нажмите на нужный вариант",
  build: "Нажимайте на карточки, чтобы собрать ответ",
};

/**
 * «Как в задаче из видео: история. Вопрос? Что сделать.» → { fromVideo, context: the story, ask: what to do }.
 * The ask is the last sentence, together with a question right before it.
 */
function questionParts(text) {
  let fromVideo = false;
  let t = String(text);
  const lead = /^Как ([^:]{2,40}):\s*/.exec(t);
  if (lead && /видео|конфет/.test(lead[1])) {
    fromVideo = true;
    t = t.slice(lead[0].length);
    t = t.charAt(0).toUpperCase() + t.slice(1);
  }
  const sentences = t.split(/(?<=[.?!])\s+(?=[А-ЯЁA-Z«])/);
  let k = sentences.length - 1;
  if (k > 0 && /\?$/.test(sentences[k - 1]) && !/\?$/.test(sentences[k])) k--;
  return { fromVideo, context: sentences.slice(0, k).join(" "), ask: sentences.slice(k).join(" ") };
}

/**
 * Quiz dialog: one question at a time. «Проверить» grades it and shows the right answer,
 * «Дальше» moves on, and after the last question the dialog shows the score.
 */
const quizDialog = (() => {
  const root = document.createElement("div");
  root.className = "modal-backdrop quiz-backdrop";
  root.hidden = true;
  root.innerHTML = `
    <section class="modal quiz-modal" role="dialog" aria-modal="true" aria-labelledby="quizModalTitle" tabindex="-1">
      <div class="sheet-handle" aria-hidden="true"></div>
      <button class="modal-close" type="button" aria-label="Закрыть тест">×</button>
      <header class="qm-head">
        <p class="section-label">Мини-тест</p>
        <h2 class="qm-title" id="quizModalTitle"></h2>
        <div class="qm-progress" aria-hidden="true"></div>
        <p class="qm-count"></p>
      </header>
      <div class="qm-scroll">
        <div class="qm-body"></div>
        <div class="qm-feedback" hidden aria-live="polite"></div>
      </div>
      <footer class="qm-foot">
        <button class="btn qm-main" type="button">Проверить</button>
      </footer>
    </section>`;
  document.body.appendChild(root);

  const dialog = root.querySelector(".quiz-modal");
  const title = root.querySelector(".qm-title");
  const progress = root.querySelector(".qm-progress");
  const count = root.querySelector(".qm-count");
  const scroller = root.querySelector(".qm-scroll");
  const body = root.querySelector(".qm-body");
  const feedback = root.querySelector(".qm-feedback");
  const main = root.querySelector(".qm-main");

  let lesson = null;
  let questions = []; // this attempt's draw: one task per slot
  // slot → variant shown last time, kept across visits, so a retry always brings a different one
  const DRAW_KEY = "intclass_quiz_draw";
  let lastDraw = {};
  try { lastDraw = JSON.parse(localStorage.getItem(DRAW_KEY)) || {}; } catch (e) { lastDraw = {}; }
  let index = 0;
  let results = [];
  let retried = []; // question index → true after a first miss on an interactive task
  let phase = "answer"; // answer → checked → (next question) … → done
  let task = null; // controller of an interactive task
  let opener = null;

  function showFeedback(kind, html) {
    feedback.hidden = false;
    feedback.className = `qm-feedback ${kind}`;
    const icon = kind === "success" ? "✓" : kind === "error" ? "✕" : "i";
    feedback.innerHTML = `<span class="qm-fb-icon" aria-hidden="true">${icon}</span><div class="qm-fb-text">${html}</div>`;
    // replay the entrance on every message, also when the same box shows a second hint
    feedback.classList.remove("is-in");
    void feedback.offsetWidth;
    feedback.classList.add("is-in");
  }

  // «Проверить» stays dim until the task has an answer, so it is clear what to do first
  function updateReady() {
    main.classList.toggle("is-waiting", phase === "answer" && currentAnswer() === null);
  }

  function renderProgress() {
    progress.innerHTML = questions
      .map((_, i) => {
        const state = results[i] === true ? "is-right" : results[i] === false ? "is-wrong" : i === index && phase !== "done" ? "is-current" : "";
        return `<span class="qm-seg ${state}"></span>`;
      })
      .join("");
  }

  function renderQuestion() {
    const q = questions[index];
    phase = "answer";
    task = null;
    feedback.hidden = true;
    count.textContent = `${q.type ? "Задание" : "Вопрос"} ${index + 1} из ${questions.length}`;
    const parts = questionParts(q.question);
    body.innerHTML = `
      <div class="quiz-question-item${q.type ? " is-task" : ""}">
        ${parts.fromVideo ? `<p class="quiz-q-tag">Задачка из видео</p>` : ""}
        ${parts.context ? `<p class="quiz-q-context"></p>` : ""}
        <p class="quiz-q-title"></p>
        ${lesson.takeaway ? `<button class="quiz-rule-btn" type="button" aria-expanded="false">Подсказка: правило урока</button>
        <div class="quiz-rule" hidden><p class="quiz-rule-text"></p></div>` : ""}
        ${q.type
          ? `<div class="task task-${q.type}" data-task="${q.type}"></div>`
          : `<div class="quiz-options" role="radiogroup">${shuffledIndices(q.options.length)
              .map((optIndex) => `
                <label class="quiz-option-label" data-opt="${optIndex}">
                  <input type="radio" name="qm-answer" value="${optIndex}">
                  <span>${q.options[optIndex]}</span>
                </label>`)
              .join("")}</div>`}
      </div>`;
    // text, not markup: inequalities like «x < 4» are plain characters
    body.querySelector(".quiz-q-title").textContent = parts.ask;
    if (parts.context) body.querySelector(".quiz-q-context").textContent = parts.context;
    const ruleBtn = body.querySelector(".quiz-rule-btn");
    if (ruleBtn) {
      const rule = body.querySelector(".quiz-rule");
      rule.querySelector(".quiz-rule-text").textContent = lesson.takeaway;
      ruleBtn.addEventListener("click", () => {
        rule.hidden = !rule.hidden;
        ruleBtn.setAttribute("aria-expanded", String(!rule.hidden));
        ruleBtn.textContent = rule.hidden ? "Подсказка: правило урока" : "Скрыть подсказку";
      });
    }
    if (q.type && window.IntTasks) {
      const box = body.querySelector(".task");
      task = window.IntTasks.mount(box, q);
      // every task says how to answer it, before the drawing
      if (!box.querySelector(".task-hint")) {
        const how = document.createElement("p");
        how.className = "task-hint";
        how.textContent = q.hint || HOW_TO[q.type] || "Выполните задание на чертеже";
        if (q.type === "words" && !q.tiles && !q.hint) how.textContent = "Нажмите на все нужные слова";
        box.prepend(how);
      }
    } else {
      const how = document.createElement("p");
      how.className = "task-hint";
      how.textContent = "Выберите один ответ";
      body.querySelector(".quiz-options").before(how);
    }
    main.textContent = "Проверить";
    renderProgress();
    updateReady();
    scroller.scrollTop = 0;
  }

  function currentAnswer() {
    if (task) return task.value();
    const selected = body.querySelector('input[type="radio"]:checked');
    return selected ? Number(selected.value) : null;
  }

  function check() {
    const q = questions[index];
    const answer = currentAnswer();
    if (answer === null) {
      showFeedback("info", q.type ? "Сначала выполните задание на чертеже." : "Сначала выберите ответ.");
      return;
    }
    const ok = q.type ? window.IntTasks.check(q, answer) : answer === q.answer;
    const item = body.querySelector(".quiz-question-item");
    // an interactive task gets a second try: a nudge first, the answer only after the second miss
    if (!ok && task && !retried[index]) {
      retried[index] = true;
      item.classList.remove("is-shake");
      void item.offsetWidth;
      item.classList.add("is-shake");
      const nudge = q.tryHint || firstSentence(lesson.takeaway);
      showFeedback("info", `<strong>Почти!</strong> Подумайте ещё раз${nudge ? `: ${escapeHtml(nudge)}` : "."}
        <button class="qm-giveup" type="button">Показать ответ</button>`);
      feedback.querySelector(".qm-giveup").addEventListener("click", () => { retried[index] = "gave-up"; check(); });
      main.textContent = "Проверить ещё раз";
      feedback.scrollIntoView({ block: "nearest", behavior: motionOn() ? "smooth" : "auto" });
      return;
    }
    results[index] = ok;
    window.IntStats?.track("answer", lesson.id, index, ok ? (retried[index] === true ? 2 : 1) : 0);
    item.classList.add(ok ? "is-correct" : "is-wrong");
    if (ok && task?.celebrate) task.celebrate();
    if (task) {
      if (!ok) task.reveal();
      task.lock(true);
    } else {
      body.querySelectorAll(".quiz-option-label").forEach((label) => {
        const opt = Number(label.dataset.opt);
        if (opt === q.answer) label.classList.add("is-correct");
        else if (opt === answer) label.classList.add("is-wrong");
        label.querySelector("input").disabled = true;
      });
    }
    const praise = retried[index] === true ? "Верно со второй попытки!" : "Верно!";
    showFeedback(ok ? "success" : "error", `<strong>${ok ? praise : "Неверно."}</strong> ${q.explanation}`);
    phase = "checked";
    main.classList.remove("is-waiting");
    main.textContent = index < questions.length - 1 ? "Дальше →" : "Показать результат";
    renderProgress();
    feedback.scrollIntoView({ block: "nearest", behavior: motionOn() ? "smooth" : "auto" });
  }

  function finish() {
    phase = "done";
    const right = results.filter(Boolean).length;
    const total = questions.length;
    const all = right === total;
    window.IntStats?.track("quiz_end", lesson.id, right);
    const record = window.IntStore?.recordQuiz(lesson.id, right, total);
    const gained = record ? record.after.xp - record.before.xp : 0;
    count.textContent = "Результат";
    feedback.hidden = true;
    body.innerHTML = `
      <div class="qm-result ${all ? "is-all" : ""}">
        <div class="qm-ring" style="--k: ${right / total}">
          <svg viewBox="0 0 120 120" aria-hidden="true"><circle class="qm-ring-bg" cx="60" cy="60" r="52"/><circle class="qm-ring-fg" cx="60" cy="60" r="52" pathLength="100"/></svg>
          <p class="qm-score"><span data-count="${right}">${motionOn() ? 0 : right}</span> из ${total}</p>
        </div>
        <div class="qm-dots" aria-label="Ответы по заданиям">${results.map((r, i) => `<i class="${r ? (retried[i] ? "is-right is-second" : "is-right") : "is-wrong"}" style="--d: ${i}" title="Задание ${i + 1}: ${r ? (retried[i] ? "верно со второй попытки" : "верно") : "неверно"}"></i>`).join("")}</div>
        <p class="qm-result-text">${all
          ? "Отлично! Все ответы верны — урок отмечен как изученный."
          : right >= total / 2
          ? "Хороший результат. Пересмотрите видео и пройдите тест ещё раз, чтобы набрать все ответы."
          : "Стоит ещё раз посмотреть видео — потом тест пойдёт легче."}</p>
        ${record ? `<p class="qm-xp">${gained > 0 ? `+${gained} XP` : "Опыт за этот тест уже получен"}<span>Уровень ${record.after.level} · ${record.after.name} · ${record.after.xp} XP</span></p>` : ""}
      </div>`;
    main.textContent = "Пройти снова";
    main.classList.remove("is-waiting");
    countUp(body.querySelector("[data-count]"));
    renderProgress();
    if (all) markCompleted(lesson.id);
    if (record && record.after.level > record.before.level && typeof window.showToast === "function") {
      window.showToast(`Новый уровень: ${record.after.level} · ${record.after.name}!`, "success", 3200);
    }
  }

  function countUp(node) {
    if (!node || !motionOn()) return;
    const to = Number(node.dataset.count), t0 = performance.now(), ms = 700;
    const step = (now) => {
      const k = Math.min(1, (now - t0) / ms);
      node.textContent = String(Math.round(to * (1 - Math.pow(1 - k, 3))));
      if (k < 1) requestAnimationFrame(step);
    };
    requestAnimationFrame(step);
  }

  ["click", "input", "change", "pointerup", "keyup"].forEach((type) =>
    body.addEventListener(type, () => requestAnimationFrame(updateReady)));

  function onMain() {
    if (phase === "answer") check();
    else if (phase === "checked") {
      if (index < questions.length - 1) {
        index++;
        renderQuestion();
      } else finish();
    } else start();
  }

  function draw() {
    // a { gen } entry is a recipe: it becomes a fresh task with new numbers on every attempt
    const make = (t) => (t.gen && window.IntGen ? window.IntGen.make(t) : t);
    return lesson.quiz.map((q, i) => {
      const list = variantsOf(q);
      if (list.length === 1) return make(list[0]);
      const key = `${lesson.id}:${i}`;
      let k = Math.floor(Math.random() * list.length);
      if (k === lastDraw[key]) k = (k + 1 + Math.floor(Math.random() * (list.length - 1))) % list.length;
      lastDraw[key] = k;
      return make(list[k]);
    });
  }

  function rememberDraw() {
    try { localStorage.setItem(DRAW_KEY, JSON.stringify(lastDraw)); } catch (e) { /* private mode: only this visit rotates */ }
  }

  function start() {
    questions = draw();
    window.IntStats?.track("quiz_start", lesson.id);
    rememberDraw();
    index = 0;
    results = [];
    retried = [];
    renderQuestion();
  }

  function open(lessonId) {
    lesson = LESSONS.find((l) => l.id === lessonId);
    if (!lesson || !lesson.quiz?.length) return;
    opener = document.activeElement;
    title.textContent = lesson.title;
    start();
    root.classList.remove("closing");
    root.hidden = false;
    document.body.classList.add("modal-open");
    dialog.focus({ preventScroll: true });
  }

  function close() {
    if (root.hidden || root.classList.contains("closing")) return;
    const done = () => {
      root.classList.remove("closing");
      root.hidden = true;
      body.innerHTML = "";
      document.body.classList.remove("modal-open");
      opener?.focus?.({ preventScroll: true });
    };
    if (!motionOn()) return done();
    root.classList.add("closing");
    setTimeout(() => root.classList.contains("closing") && done(), 220);
  }

  main.addEventListener("click", onMain);
  root.querySelector(".modal-close").addEventListener("click", close);
  root.addEventListener("click", (event) => {
    if (event.target === root) close();
  });
  body.addEventListener("change", (event) => {
    if (event.target.matches('input[type="radio"]')) {
      body.querySelectorAll(".quiz-option-label").forEach((label) => label.classList.toggle("checked", label.contains(event.target)));
      feedback.hidden = true;
    }
  });
  document.addEventListener("keydown", (event) => {
    if (event.key === "Escape" && !root.hidden) close();
  });

  return { open, close };
})();

function motionOn() {
  return document.documentElement.classList.contains("anim");
}

// The video has ended: leave full screen first, then open the questions
function openQuizAfterVideo(lessonId) {
  const watched = window.IntStore?.markWatched(lessonId);
  if (watched && typeof window.showToast === "function") {
    window.showToast(`+${watched.after.xp - watched.before.xp} XP за просмотр видео`, "success");
  }
  const go = () => quizDialog.open(lessonId);
  if (document.fullscreenElement && document.exitFullscreen) document.exitFullscreen().then(go, go);
  else go();
}

// All answers right (already saved by the store): celebrate and mark the card
function markCompleted(lessonId) {
  launchConfetti();
  if (typeof window.showToast === "function") {
    window.showToast("Поздравляем! Урок и тест успешно пройдены 🎉", "success");
  }
  const card = document.getElementById(`card-${lessonId}`);
  if (card) {
    card.classList.add("is-completed");
    const text = card.querySelector(".quiz-lock-text");
    const icon = card.querySelector(".quiz-lock-icon");
    const btn = card.querySelector(".quiz-unlock-btn");
    if (text) text.textContent = "Тест успешно пройден";
    if (icon) icon.textContent = "✓";
    if (btn) btn.textContent = "Пройти снова →";
    const media = card.querySelector(".lesson-media");
    if (media && !card.querySelector(".lesson-completed-ribbon")) {
      const ribbon = document.createElement("div");
      ribbon.className = "lesson-completed-ribbon";
      ribbon.textContent = "✓ Изучено";
      media.appendChild(ribbon);
    }
  }
  updateOverallProgressStats();
}

// «Пройти тест» on a card
function handleQuizInteraction(event) {
  const unlockBtn = event.target.closest(".quiz-unlock-btn");
  if (unlockBtn) quizDialog.open(unlockBtn.dataset.unlock);
}

/**
 * Handle card actions (Bookmark toggle & Share copy link)
 */
function handleCardAction(event) {
  // Bookmark toggle
  const bookmarkBtn = event.target.closest("[data-bookmark]");
  if (bookmarkBtn) {
    event.stopPropagation();
    const lessonId = bookmarkBtn.dataset.bookmark;
    const isNowSaved = toggleBookmark(lessonId);
    bookmarkBtn.classList.toggle("active", isNowSaved);
    const icon = bookmarkBtn.querySelector(".bookmark-icon");
    if (icon) icon.textContent = isNowSaved ? "★" : "☆";
    bookmarkBtn.setAttribute("title", isNowSaved ? "В избранном" : "В закладки");

    if (typeof window.showToast === "function") {
      window.showToast(isNowSaved ? "Урок добавлен в избранное ★" : "Урок удалён из избранного", "info");
    }

    if (state.activeFilter === "favorites") {
      renderLessons();
    }
    return true;
  }

  // Share link copy
  const shareBtn = event.target.closest("[data-share]");
  if (shareBtn) {
    event.stopPropagation();
    const lessonId = shareBtn.dataset.share;
    const lesson = LESSONS.find((l) => l.id === lessonId);
    if (!lesson) return true;

    const shareUrl = `${location.origin}${location.pathname}?subject=${lesson.subject}&grade=${lesson.grade}&topic=${lesson.id}`;

    if (navigator.clipboard && navigator.clipboard.writeText) {
      navigator.clipboard
        .writeText(shareUrl)
        .then(() => {
          if (typeof window.showToast === "function") {
            window.showToast("Ссылка на урок скопирована в буфер!", "success");
          }
        })
        .catch(() => {
          prompt("Скопируйте ссылку на урок:", shareUrl);
        });
    } else {
      prompt("Скопируйте ссылку на урок:", shareUrl);
    }
    return true;
  }

  return false;
}

/**
 * Step Selection Functions
 */
function selectSubject(subject) {
  state.subject = subject;
  state.topic = null;

  document.querySelectorAll("[data-subject]").forEach((button) => {
    button.classList.toggle("selected", button.dataset.subject === subject);
  });

  gradeStep?.classList.remove("is-locked");

  document.querySelectorAll("[data-grade]").forEach((btn) => {
    const isSelected = (!state.grade && btn.dataset.grade === "all") || btn.dataset.grade === state.grade;
    btn.classList.toggle("selected", isSelected);
  });

  if (gradeHint) gradeHint.textContent = `${SUBJECT_LABELS[subject]} — выберите класс`;
  renderTopics();
  renderLessons();
  showPane(2);
}

function selectGrade(gradeVal) {
  if (!state.subject) return;

  state.grade = gradeVal === "all" || !gradeVal ? null : gradeVal;
  state.topic = null;

  document.querySelectorAll("[data-grade]").forEach((btn) => {
    const isSelected = (!state.grade && btn.dataset.grade === "all") || btn.dataset.grade === state.grade;
    btn.classList.toggle("selected", isSelected);
  });

  if (topicHint) {
    topicHint.textContent = `${SUBJECT_LABELS[state.subject]} · ${state.grade ? `${state.grade} класс` : "все классы"} — выберите тему, откроется видео и тест`;
  }
  renderTopics();
  renderLessons();
  showPane(3);
}

function selectTopic(topicVal) {
  if (state.topic === topicVal) {
    state.topic = null;
  } else {
    state.topic = topicVal;
  }

  topicChoices?.querySelectorAll(".topic-chip").forEach((btn) => {
    btn.classList.toggle("selected", btn.dataset.topic === state.topic);
  });

  renderLessons();

  if (state.topic) {
    const targetCard = document.getElementById(`card-${state.topic}`);
    if (targetCard) {
      targetCard.scrollIntoView({ behavior: "smooth", block: "nearest" });
      const media = targetCard.querySelector(".lesson-media");
      if (media && !media.querySelector("iframe, video")) {
        playVideo(media);
      }
    }
  }
}

// Global hook to refresh progress badges if user resets in profile modal
window.reloadLessonsProgress = function () {
  renderLessons();
};

// Event Listeners: step tabs and back arrows inside the box
flowBox?.addEventListener("click", (event) => {
  const go = event.target.closest("[data-go], [data-step-indicator]");
  if (!go || go.disabled) return;
  showPane(Number(go.dataset.go || go.dataset.stepIndicator));
});

// Event Listeners: Step buttons
document.querySelectorAll("[data-subject]").forEach((button) => {
  button.addEventListener("click", () => {
    selectSubject(button.dataset.subject);
  });
});

document.querySelectorAll("[data-grade]").forEach((button) => {
  button.addEventListener("click", () => {
    selectGrade(button.dataset.grade);
  });
});

topicChoices?.addEventListener("click", (event) => {
  const button = event.target.closest("[data-topic]");
  if (!button) return;
  selectTopic(button.dataset.topic);
});

// Event Listeners: Filter tabs
// «С видео» would show the same list as «Все уроки» while every lesson has a video
const videoFilterBtn = document.querySelector('.filter-tab-btn[data-filter="video"]');
if (videoFilterBtn && LESSONS.every((l) => l.video || l.videoId)) videoFilterBtn.hidden = true;
document.querySelectorAll(".filter-tab-btn").forEach((btn) => {
  btn.addEventListener("click", () => {
    document.querySelectorAll(".filter-tab-btn").forEach((b) => b.classList.remove("active"));
    btn.classList.add("active");
    state.activeFilter = btn.dataset.filter || "all";
    renderLessons();
  });
});

// Event Listeners: Search input & Clear
let searchDebounceTimeout = null;
if (lessonSearchInput) {
  lessonSearchInput.addEventListener("input", () => {
    clearTimeout(searchDebounceTimeout);
    searchDebounceTimeout = setTimeout(() => {
      state.searchQuery = lessonSearchInput.value.trim();
      if (clearSearchBtn) {
        clearSearchBtn.hidden = !state.searchQuery;
      }
      renderLessons();
    }, 180);
  });

  clearSearchBtn?.addEventListener("click", () => {
    lessonSearchInput.value = "";
    state.searchQuery = "";
    clearSearchBtn.hidden = true;
    renderLessons();
    lessonSearchInput.focus();
  });

  // Shortcut '/' or 'Ctrl+K' to focus search
  document.addEventListener("keydown", (e) => {
    if (
      (e.key === "/" && document.activeElement !== lessonSearchInput && !["INPUT", "TEXTAREA"].includes(document.activeElement.tagName)) ||
      ((e.ctrlKey || e.metaKey) && e.key.toLowerCase() === "k")
    ) {
      e.preventDefault();
      lessonSearchInput.focus();
      lessonSearchInput.scrollIntoView({ behavior: "smooth", block: "center" });
    } else if (e.key === "Escape" && document.activeElement === lessonSearchInput) {
      lessonSearchInput.blur();
    }
  });
}

// Event Listeners: Lesson Grid
grid?.addEventListener("click", (event) => {
  if (handleCardAction(event)) return;

  const media = event.target.closest(".lesson-media");
  if (media) {
    playVideo(media);
    return;
  }
  handleQuizInteraction(event);
});

grid?.addEventListener("keydown", (event) => {
  const media = event.target.closest(".lesson-media");
  // once the player is showing, keys belong to its own controls (Space = pause)
  if (media && !media.querySelector("video, iframe") && ["Enter", " "].includes(event.key)) {
    event.preventDefault();
    playVideo(media);
  }
});

// Reset Flow
resetFlowBtn?.addEventListener("click", () => {
  state.subject = null;
  state.grade = null;
  state.topic = null;
  state.searchQuery = "";
  state.activeFilter = "all";

  if (lessonSearchInput) lessonSearchInput.value = "";
  if (clearSearchBtn) clearSearchBtn.hidden = true;

  document.querySelectorAll("[data-subject], [data-grade]").forEach((btn) => {
    btn.classList.remove("selected");
  });

  document.querySelectorAll(".filter-tab-btn").forEach((b) => {
    b.classList.toggle("active", b.dataset.filter === "all");
  });

  if (topicChoices) topicChoices.innerHTML = "";
  if (grid) grid.innerHTML = "";
  gradeStep?.classList.add("is-locked");
  topicStep?.classList.add("is-locked");
  resultsPanel?.classList.add("is-locked");
  maxPane = 1;
  showPane(1);
  updateUrl();
});

// Initialize from URL parameters
(function initFromUrl() {
  const params = new URLSearchParams(window.location.search);
  const initialSubject = params.get("subject");
  const initialGrade = params.get("grade");
  const initialTopic = params.get("topic");
  const initialQuery = params.get("q");

  if (initialQuery && lessonSearchInput) {
    lessonSearchInput.value = initialQuery;
    state.searchQuery = initialQuery;
    if (clearSearchBtn) clearSearchBtn.hidden = false;
  }

  if (initialSubject && SUBJECT_LABELS[initialSubject]) {
    selectSubject(initialSubject);
    if (initialGrade && ["5", "6", "7", "8", "9"].includes(initialGrade)) {
      selectGrade(initialGrade);
    }
    if (initialTopic && LESSONS.some((l) => l.id === initialTopic)) {
      selectTopic(initialTopic);
    }
  } else if (initialQuery) {
    renderLessons();
  } else {
    updateProgressIndicator();
    updateOverallProgressStats();
  }
  booting = false;
})();

// Listen for YouTube video ended message to unlock quiz
window.addEventListener("message", (event) => {
  if (event.origin !== "https://www.youtube-nocookie.com") return;
  try {
    const data = typeof event.data === "string" ? JSON.parse(event.data) : event.data;
    if (data?.event !== "onStateChange" || data.info !== 0) return;
    document.querySelectorAll(".lesson-card iframe").forEach((iframe) => {
      if (iframe.contentWindow === event.source) {
        const lessonId = iframe.closest(".lesson-card")?.querySelector(".quiz-unlock-btn")?.dataset.unlock;
        if (lessonId) openQuizAfterVideo(lessonId);
      }
    });
  } catch {}
});

} // end initLessonsApp

// Node.js module export for unit tests
if (typeof module !== "undefined" && module.exports) {
  module.exports = { LESSONS, SUBJECT_LABELS };
}
